::selection { color: var(--whatiuse-on-inverse); background: var(--whatiuse-inverse); }

:focus-visible { outline: var(--whatiuse-focus-width) solid var(--whatiuse-focus-control); outline-offset: var(--whatiuse-focus-offset); }

.whatiuse-sr-only,
.whatiuse-sr-only:not(:focus):not(:active) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}
